import{_ as d,C as t,o as n,c as i,E as a,a2 as l}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/control-intent-20260917/quota-behind-error-code.figure.zh.svg",f=JSON.parse('{"title":"额度已经耗尽，AI 为什么还在重试？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"额度已经耗尽，AI 为什么还在重试？","date":"2026-09-17","published_date":"2026-09-17","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"额度已经耗尽，AI 为什么还在重试？","summary":"服务已经说清恢复时间，程序却可能只记住“这一轮失败了”。我们对照同一段错误文本，检查它怎样从普通失败变成等待额度恢复。","cover":"/assets/control-intent-20260917/quota-behind-error-code.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码有界实验；范围见正文","pageClass":"control-intent-article"},"headers":[],"relativePath":"zh/engineering/2026-09-17-quota-behind-error-code.md","filePath":"zh/engineering/2026-09-17-quota-behind-error-code.md","lastUpdated":1789614884000}'),p={name:"zh/engineering/2026-09-17-quota-behind-error-code.md"};function s(h,e,u,b,m,g){const r=t("ArticleCover"),o=t("ArticleTableScroll");return n(),i("div",null,[a(r,{image:"/assets/control-intent-20260917/quota-behind-error-code.cover-v1.png",kicker:"开源工程观察 · 实验研究",title:"额度已经耗尽，AI 为什么还在重试？",summary:"服务已经说清恢复时间，程序却可能只记住“这一轮失败了”。我们对照同一段错误文本，检查它怎样从普通失败变成等待额度恢复。",version:"2026-09-17",languageHref:"/en/engineering/2026-09-17-quota-behind-error-code",languageLabel:"English"}),a(o,{language:"zh"}),e[0]||(e[0]=l('<h1 id="额度已经耗尽-ai-为什么还在重试" tabindex="-1">额度已经耗尽，AI 为什么还在重试？ <a class="header-anchor" href="#额度已经耗尽-ai-为什么还在重试" aria-label="Permalink to &quot;额度已经耗尽，AI 为什么还在重试？&quot;">​</a></h1><p>AI 助手停了，服务明明告诉它：“本轮额度已用完，今晚恢复。”</p><p>过一会儿，它却又试了一次。重试次数增加，工作没有前进。程序究竟没有读懂哪句话？</p><p>一种可能是：服务说出了失败原因，程序只记下“这一步失败了”。就像快递员告诉你“今天仓库关门”，系统却只登记“本次配送失败”，于是照常安排下一趟。</p><h2 id="原因是在什么地方丢掉的" tabindex="-1">原因是在什么地方丢掉的？ <a class="header-anchor" href="#原因是在什么地方丢掉的" aria-label="Permalink to &quot;原因是在什么地方丢掉的？&quot;">​</a></h2><p>这个问题来自 electrumnz 提交的 <a href="https://github.com/paperclipai/paperclip/pull/13549" target="_blank" rel="noreferrer">Paperclip #13549</a>。Paperclip 管理持续运行的 AI 工作，其中包含失败后的恢复安排。</p><p>作者报告，一次生产检查发现 320 条额度相关的终止运行，其中 186 条带有重试关联，额度原因却没有被正确登记。这是上游的调查，我们没有访问那套生产数据。它让我们感兴趣，是因为“失败再来一次”对网络波动或许有用，对尚未恢复的额度却可能只是在重复碰壁。</p><p>程序要决定下一步，先得判断失败原因。这次修改补上了一个原先漏掉的入口：当消息以“这一轮执行失败”的错误码到达时，也去检查其中有没有额度信息。</p><p>所以，关键不只在于服务有没有说清楚，还在于<strong>这句话有没有到达负责决定等待时间的那段代码</strong>。</p><h2 id="让同一句话-再走一遍" tabindex="-1">让同一句话，再走一遍 <a class="header-anchor" href="#让同一句话-再走一遍" aria-label="Permalink to &quot;让同一句话，再走一遍&quot;">​</a></h2><p>我们取出修改前后的原始分类代码及解析辅助函数，提供相同的九组输入。其中一条消息说额度已经耗尽，并给出了恢复时间。</p><table tabindex="0"><thead><tr><th>输入</th><th>修改前</th><th>候选版本</th></tr></thead><tbody><tr><td>带恢复时间的额度消息，经“本轮失败”入口到达</td><td>没有给出分类</td><td>识别为额度限制，算出服务消息对应的恢复时间</td></tr><tr><td>额度消息，没有恢复时间</td><td>没有给出分类</td><td>识别为额度限制，给出默认一小时等待</td></tr><tr><td>普通网络错误</td><td>没有给出分类</td><td>仍没有给出分类</td></tr><tr><td>缺少密钥，经原有适配器失败入口到达</td><td>配置不完整</td><td>仍是配置不完整</td></tr></tbody></table><p>前两行都得到了一个等待时间，但依据不同：一条是从服务消息里读出来的，另一条是程序在信息不足时采用的默认值。</p><p>这一区别会影响人的判断。看到“请等到某个时间”，人很容易以为服务已经保证届时恢复；<strong>默认等待一小时，只说明程序打算隔一小时再试，并不包含这种保证。</strong></p><p><img src="'+c+'" alt="等待时间相同的外观，可能有不同依据"></p><p><em>图 1：来源：作者依据两版原函数的分类输出绘制。准确时间与时区换算保留在文末实验补充。</em></p><p>这里验证的是“分类代码给出了什么”。真正负责安排下一次执行的程序是否照此等待，还需要再接着测。单凭这张表，不能宣布整个重试问题已经解决。</p><h2 id="有-额度-这个词-也可能是在否认额度问题" tabindex="-1">有“额度”这个词，也可能是在否认额度问题 <a class="header-anchor" href="#有-额度-这个词-也可能是在否认额度问题" aria-label="Permalink to &quot;有“额度”这个词，也可能是在否认额度问题&quot;">​</a></h2><p>我们又故意给它一句话，中文意思是：“没有超出额度，网络连接失败。”实际输入的英文原文是：</p><blockquote><p>No quota exceeded. Socket failed.</p></blockquote><p>候选函数仍把它归为额度问题，并给出默认一小时等待。</p><p>这句话是我们人为构造的反例，没有证据表明真实服务会这样报错。它说明了关键词匹配的一条边界：看见某个词，还不一定读懂了整句话。</p><p>另一组输入提供了无法识别的时区，程序也退回默认等待。由此看，同样精确的时间显示，背后可能是有效解析，也可能只是备用规则。记录下这个区别，才能解释程序为什么这样等。</p><h2 id="一个时间-还需要一句解释" tabindex="-1">一个时间，还需要一句解释 <a class="header-anchor" href="#一个时间-还需要一句解释" aria-label="Permalink to &quot;一个时间，还需要一句解释&quot;">​</a></h2><p>进一步值得探索的是，让服务连接程序直接传递明确的失败原因和恢复时间，减少靠文字猜测；确实需要猜测或使用默认值时，也保留依据。这是后续方向，本轮仍只完成了分类函数对照。</p><p>普通使用者也能帮忙验证后半段：保留当时的提示语和时间，再记录重试次数是否继续增长、提示时间到了以后任务有没有恢复。这能帮助开发者把“原因已经识别”与“后续确实等待”连起来。</p><p><strong>工具告诉你“请等到这个时间”时，它能不能同时说明，这个时间是服务告知的，还是程序估出来的？</strong></p><details><summary>固定版本与实验边界</summary><h3 id="保留的完整数值对照" tabindex="-1">保留的完整数值对照 <a class="header-anchor" href="#保留的完整数值对照" aria-label="Permalink to &quot;保留的完整数值对照&quot;">​</a></h3><p>实验时钟固定为 2026-09-16 04:50 UTC。额度消息指定 21:20 Pacific/Auckland，解析得到 09:20 UTC；无恢复时间时默认加一小时，得到 05:50 UTC。本轮读取时 PR 仍 open，固定来源状态不代表之后没有变化。</p><p>受测新增入口标识为 <code>acpx_turn_failed</code>（本轮执行失败）；输出的 <code>parsedResetTime</code> 用来区分是否解析到了恢复时间。“没有给出分类”是本函数返回 null，不表示后续所有处理都一定直接重试。</p><table tabindex="0"><thead><tr><th>输入</th><th>修改前</th><th>候选版本</th></tr></thead><tbody><tr><td>上述额度消息，经“本轮失败”入口到达</td><td>没有给出分类</td><td>额度限制；09:20 UTC 重试</td></tr><tr><td>额度消息，没有恢复时间</td><td>没有给出分类</td><td>额度限制；05:50 UTC 重试</td></tr><tr><td>普通网络错误</td><td>没有给出分类</td><td>仍没有给出分类</td></tr><tr><td>缺少密钥，经原有适配器失败入口到达</td><td>配置不完整</td><td>仍是配置不完整</td></tr></tbody></table><p>基线 <code>d0b67bfe71277f5a5ad21c7a7b6cb7af09e2ccca</code>；候选 <code>688c994a95d6c447816c50b14e30745d8ea9e855</code>。使用受检锚点提取原分类函数块及原始解析辅助函数，9 输入 × 2 版本，共 18 条观察，不是 18 次真实服务调用。</p><p>补充场景覆盖结构化 retryNotBefore（得到 12:00 UTC）、未知错误码、无效时区，以及缺少密钥通过不同入口时的表现。否定句仅为人为边界输入。没有运行真实调度器、数据库恢复扫描、生产账户或模型调用。</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-17-control-intent" target="_blank" rel="noreferrer">全部结果与复跑脚本</a>。没有据此认定 CodeFlowMu 具有同一错误入口或额度重试缺陷。</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">研究仓库</a></p>',29))])}const q=d(p,[["render",s]]);export{f as __pageData,q as default};
